@pytest.mark.parametrize(
    "options, diagnostic",
    [
        (["--unknown-option=yes"], "unknown-option=yes"),
        (["-Q"], "Q"),
        (["-Q", "--unknown-option=yes"], "Q, unknown-option=yes"),
    ],
)
@pytest.mark.parametrize("files", [[], [str(EMPTY_MODULE)]])
def test_unknown_option_name(
    capsys: CaptureFixture, options: list[str], diagnostic: str, files: list[str]
) -> None:
    """Unknown command-line options should exit with a usage error."""
    with pytest.raises(SystemExit) as exc:
        Run(files + options, exit=False)
    assert exc.value.code == 2
    output = capsys.readouterr()
    assert "usage:" in output.err
    assert f"Unrecognized option found: {diagnostic}" in output.err
